class Solution {
    long long key(int x, int y) {
        return (static_cast<long long>(static_cast<unsigned int>(x)) << 32) |
               static_cast<unsigned int>(y);
    }
public:
    int robotSim(vector<int>& commands, vector<vector<int>>& obstacles) {
        unordered_set<long long> blocked;
        for (const auto& o : obstacles) blocked.insert(key(o[0], o[1]));
        int dx[] = {0, 1, 0, -1}, dy[] = {1, 0, -1, 0};
        int x = 0, y = 0, dir = 0, best = 0;
        for (int cmd : commands) {
            if (cmd == -1) dir = (dir + 1) % 4;
            else if (cmd == -2) dir = (dir + 3) % 4;
            else for (int step = 0; step < cmd; ++step) {
                int nx = x + dx[dir], ny = y + dy[dir];
                if (blocked.count(key(nx, ny))) break;
                x = nx; y = ny;
                best = max(best, x * x + y * y);
            }
        }
        return best;
    }
};
